SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsTransferLineContract
{
    LineNum             lineNumber;
    ItemId              itemId;
    Name                itemName;
    UnitOfMeasureSymbol unitId;

    InventQty           transferQty;
    InventQty           shippedQty;
    InventQty           receivedQty;
    InventQty           remainingQty;

    InventSiteId        fromSiteId;
    InventLocationId    fromWarehouseId;
    InventSiteId        toSiteId;
    InventLocationId    toWarehouseId;
    WMSLocationId       locationId;

    boolean             batchRequired;
    boolean             serialRequired;
    boolean             locationRequired;

}

Method.Source:
[DataMemberAttribute('LineNumber')]
public LineNum parmLineNumber(LineNum _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('ItemId')]
public ItemId parmItemId(ItemId _value = itemId)
{
    itemId = _value;
    return itemId;
}

[DataMemberAttribute('ItemName')]
public Name parmItemName(Name _value = itemName)
{
    itemName = _value;
    return itemName;
}

[DataMemberAttribute('UnitId')]
public UnitOfMeasureSymbol parmUnitId(UnitOfMeasureSymbol _value = unitId)
{
    unitId = _value;
    return unitId;
}

[DataMemberAttribute('TransferQty')]
public InventQty parmTransferQty(InventQty _value = transferQty)
{
    transferQty = _value;
    return transferQty;
}

[DataMemberAttribute('ShippedQty')]
public InventQty parmShippedQty(InventQty _value = shippedQty)
{
    shippedQty = _value;
    return shippedQty;
}

[DataMemberAttribute('ReceivedQty')]
public InventQty parmReceivedQty(InventQty _value = receivedQty)
{
    receivedQty = _value;
    return receivedQty;
}

/// <summary>
/// What is outstanding *for the requested direction* - remaining to ship, or remaining to
/// receive. Named without a direction on purpose: the client drives one flow and should not
/// have to know which field it is looking at.
///
/// Note the two are not the same number even on an untouched order, and on a partly shipped
/// one they never are. Receiving is bounded by what was shipped, not by what was ordered.
/// </summary>
[DataMemberAttribute('RemainingQty')]
public InventQty parmRemainingQty(InventQty _value = remainingQty)
{
    remainingQty = _value;
    return remainingQty;
}

[DataMemberAttribute('FromSiteId')]
public InventSiteId parmFromSiteId(InventSiteId _value = fromSiteId)
{
    fromSiteId = _value;
    return fromSiteId;
}

[DataMemberAttribute('FromWarehouseId')]
public InventLocationId parmFromWarehouseId(InventLocationId _value = fromWarehouseId)
{
    fromWarehouseId = _value;
    return fromWarehouseId;
}

[DataMemberAttribute('ToSiteId')]
public InventSiteId parmToSiteId(InventSiteId _value = toSiteId)
{
    toSiteId = _value;
    return toSiteId;
}

[DataMemberAttribute('ToWarehouseId')]
public InventLocationId parmToWarehouseId(InventLocationId _value = toWarehouseId)
{
    toWarehouseId = _value;
    return toWarehouseId;
}

/// <summary>
/// The line's own location on the source side. A hint for shipping, never an answer for
/// receiving - where the goods are put away is what the operator scans.
/// </summary>
[DataMemberAttribute('LocationId')]
public WMSLocationId parmLocationId(WMSLocationId _value = locationId)
{
    locationId = _value;
    return locationId;
}

[DataMemberAttribute('BatchRequired')]
public boolean parmBatchRequired(boolean _value = batchRequired)
{
    batchRequired = _value;
    return batchRequired;
}

[DataMemberAttribute('SerialRequired')]
public boolean parmSerialRequired(boolean _value = serialRequired)
{
    serialRequired = _value;
    return serialRequired;
}

[DataMemberAttribute('LocationRequired')]
public boolean parmLocationRequired(boolean _value = locationRequired)
{
    locationRequired = _value;
    return locationRequired;
}
